package com.agacostays.payroll.controller; import com.agacostays.payroll.dto.request.*;import com.agacostays.payroll.dto.response.*;import com.agacostays.payroll.security.CurrentUserProvider;import com.agacostays.payroll.service.PayrollService;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/manager/payroll") public class PayrollController{final PayrollService s;final CurrentUserProvider c;public PayrollController(PayrollService s,CurrentUserProvider c){this.s=s;this.c=c;}@PostMapping("/generate") public ResponseEntity<ApiResponse<java.util.List<PayrollResponse>>> generate(@Valid @RequestBody GeneratePayrollRequest r){return ResponseEntity.ok(ApiResponse.ok("Payroll generated",s.generate(r,c.userId())));}@PostMapping("/staff/{staffId}/generate") public ResponseEntity<ApiResponse<PayrollResponse>> one(@PathVariable Long staffId,@Valid @RequestBody GeneratePayrollRequest r){return ResponseEntity.ok(ApiResponse.ok("Staff payroll generated",s.generateForStaff(staffId,r,c.userId())));}@GetMapping public ResponseEntity<ApiResponse<PageResponse<PayrollResponse>>> search(@RequestParam(required=false)Integer month,@RequestParam(required=false)Integer year,@RequestParam(required=false)Long branchId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ResponseEntity.ok(ApiResponse.ok("Payroll fetched",s.search(month,year,branchId,page,size)));}@GetMapping("/{id}") public ResponseEntity<ApiResponse<PayrollResponse>> get(@PathVariable Long id){return ResponseEntity.ok(ApiResponse.ok("Payroll fetched",s.get(id)));}@GetMapping("/staff/{staffId}") public ResponseEntity<ApiResponse<java.util.List<PayrollResponse>>> staff(@PathVariable Long staffId){return ResponseEntity.ok(ApiResponse.ok("Staff payroll fetched",s.staffPayroll(staffId)));}@PutMapping("/{id}") public ResponseEntity<ApiResponse<PayrollResponse>> update(@PathVariable Long id,@RequestBody GeneratePayrollRequest r){return ResponseEntity.ok(ApiResponse.ok("Payroll updated",s.update(id,r,c.userId())));}@GetMapping("/{id}/payment-status") public ResponseEntity<ApiResponse<SalaryCreditResponse>> status(@PathVariable Long id){return ResponseEntity.ok(ApiResponse.ok("Payment status fetched",s.paymentStatus(id)));}@PostMapping("/{id}/retry-payment") public ResponseEntity<ApiResponse<SalaryCreditResponse>> retry(@PathVariable Long id){return ResponseEntity.ok(ApiResponse.ok("Payment retry completed",s.retry(id,c.userId())));}}
